*   **`table class="table table-bordered"`:**  This uses Bootstrap's base table styling and adds borders.
*   **`<thead>`:**  Contains the table headers.
*   **`<th>`:**  Each header cell.  Crucially, we add a `data-sort` attribute to each `<th>`.  This attribute tells our JavaScript what type of sorting to apply to that column.  Possible values:
    *   `string`: For text-based sorting (alphanumeric).
    *   `number`: For numeric sorting.
    *   `date`: For date sorting (assuming a standard date format like YYYY-MM-DD).
*   **`<tbody>`:**  Contains the table data rows.
*   **`<tr>`:**  Each data row.
*   **`<td>`:**  Each data cell.

**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');
let sortColumn = 0; // Default sort column
let sortOrder = 1; // 1 = ascending, -1 = descending

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const columnIndex = Array.from(event.target.parentNode.children).indexOf(event.target);
    const sortType = event.target.dataset.sort;

    // Toggle sort order if clicking the same column
    if (columnIndex === sortColumn) {
      sortOrder *= -1;
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(sortColumn, sortOrder, sortType);
  }
});

function sortTable(column, order, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.querySelectorAll('td')[column].textContent;
    const cellB = b.querySelectorAll('td')[column].textContent;

    let valueA, valueB;

    switch (sortType) {
      case 'number':
        valueA = parseFloat(cellA);
        valueB = parseFloat(cellB);
        break;
      case 'date':
        valueA = new Date(cellA);
        valueB = new Date(cellB);
        break;
      default: // string
        valueA = cellA.toLowerCase(); // Case-insensitive sorting
        valueB = cellB.toLowerCase();
    }

    if (valueA < valueB) {
      return order * -1;
    }
    if (valueA > valueB) {
      return order;
    }
    return 0;
  });

  // Re-append sorted rows to the table body
  const tbody = table.querySelector('tbody');
  rows.forEach(row => tbody.appendChild(row));
}
```

